#!/usr/bin/env node
// Publishes static sites on Cloudflare (Workers Static Assets or Pages). Local files are generated by scaffold;
// every Cloudflare API change is printed as a plan and runs only with --apply. The API token is read from the
// environment and is never printed or written to disk.
import { resolve } from 'node:path';
import { UsageError, parseArgs, parseBoolean, requireChoice, requireOption } from './lib/args.mjs';
import { configureAccess } from './lib/access.mjs';
import { ApiError, createApiClient } from './lib/cloudflare-api.mjs';
import {
  DEFAULT_BRANCH,
  DEFAULT_SESSION_DURATION,
  ENV_ACCOUNT_ID,
  ENV_API_TOKEN,
  EXIT_FAILURE,
  EXIT_OK,
  EXIT_USAGE,
  GIT_MODES,
  GIT_NONE,
  JSON_INDENT,
  NOT_FOUND_MODES,
  PLATFORMS,
} from './lib/constants.mjs';
import { detectPackageManager, detectProject } from './lib/detect.mjs';
import { configureDns } from './lib/dns.mjs';
import { addPagesDomains } from './lib/pages-domain.mjs';
import { scaffold } from './lib/scaffold.mjs';
import { verifyUrl } from './lib/verify.mjs';

const USAGE = `usage:
  cf-publish.mjs detect [--cwd DIR]
  cf-publish.mjs scaffold --platform workers|pages --name NAME --dir OUTPUT_DIR [--build SCRIPT]
                 [--not-found spa|404|none] [--domain HOST]... [--protect] [--git github-actions|native|none]
                 [--manual-script true|false] [--branch main] [--cwd DIR] [--dry-run] [--force]
  cf-publish.mjs auth [--account-id ID]
  cf-publish.mjs access --hostname HOST... (--email ADDR... | --email-domain DOMAIN...) [--name NAME]
                 [--session 24h] [--account-id ID] [--apply]
  cf-publish.mjs pages-domain --project NAME --domain HOST... [--account-id ID] [--apply]
  cf-publish.mjs dns --hostname HOST --target TARGET [--zone ZONE] [--proxied true|false] [--external] [--apply]
  cf-publish.mjs verify --url URL... [--expect-access]
environment: ${ENV_API_TOKEN} (API calls), ${ENV_ACCOUNT_ID} (or --account-id)`;

function print(value) {
  process.stdout.write(`${JSON.stringify(value, null, JSON_INDENT)}\n`);
}

function tokenFromEnv() {
  return process.env[ENV_API_TOKEN] || null;
}

function accountIdOf(options) {
  const accountId = options['account-id'] ?? process.env[ENV_ACCOUNT_ID];
  if (!accountId) throw new UsageError(`account id missing: pass --account-id or set ${ENV_ACCOUNT_ID}`);
  return accountId;
}

function apiClient(options) {
  const token = tokenFromEnv();
  if (options.apply && !token) throw new UsageError(`--apply needs ${ENV_API_TOKEN} in the environment`);
  return createApiClient({ token, apply: Boolean(options.apply) });
}

function modeOf(options) {
  return options.apply ? 'apply' : 'plan';
}

// Keeps the steps already done when a later API call fails, so a partial apply is reported and can be resumed.
async function runWithClient(options, action) {
  const client = apiClient(options);
  try {
    const result = await action(client);
    return { mode: modeOf(options), result, steps: client.steps };
  } catch (error) {
    if (!(error instanceof ApiError)) throw error;
    return { ok: false, mode: modeOf(options), error: error.message, steps: client.steps };
  }
}

function siteFromOptions(options, cwd) {
  const platform = requireChoice(requireOption(options, 'platform'), PLATFORMS, 'platform');
  const git = requireChoice(options.git ?? GIT_NONE, GIT_MODES, 'git');
  return {
    platform,
    name: requireOption(options, 'name'),
    dir: requireOption(options, 'dir'),
    build: options.build ?? null,
    notFound: requireChoice(options['not-found'] ?? 'none', Object.keys(NOT_FOUND_MODES), 'not-found'),
    domains: options.domain ?? [],
    protect: Boolean(options.protect),
    git,
    manualScript: parseBoolean(options['manual-script'], 'manual-script', true),
    branch: options.branch ?? DEFAULT_BRANCH,
    packageManager: detectPackageManager(cwd).manager ?? 'npm',
    force: Boolean(options.force),
  };
}

async function runScaffold(options) {
  const cwd = resolve(options.cwd ?? '.');
  const site = siteFromOptions(options, cwd);
  const files = scaffold(cwd, site, { dryRun: Boolean(options['dry-run']) });
  const { force, ...settings } = site;
  return { cwd, settings, files };
}

async function runAuth(options) {
  const token = tokenFromEnv();
  if (!token) return { ok: false, reason: `${ENV_API_TOKEN} not set` };
  const client = createApiClient({ token, apply: false });
  const accountId = options['account-id'] ?? process.env[ENV_ACCOUNT_ID];
  const path = accountId ? `/accounts/${accountId}/tokens/verify` : '/user/tokens/verify';
  try {
    const result = await client.read('Verify the API token', path);
    return { ok: result?.status === 'active', tokenStatus: result?.status ?? null, scope: accountId ? 'account' : 'user', expiresOn: result?.expires_on ?? null };
  } catch (error) {
    if (!(error instanceof ApiError) || accountId) throw error;
    return { ok: false, reason: `${error.message}. An account-owned token is verified per account: pass --account-id or set ${ENV_ACCOUNT_ID}` };
  }
}

async function runAccess(options) {
  const emails = options.email ?? [];
  const emailDomains = options['email-domain'] ?? [];
  if (emails.length + emailDomains.length === 0) throw new UsageError('pass at least one --email or --email-domain: Access denies everyone not matched by an allow rule');
  const settings = {
    accountId: accountIdOf(options),
    hostnames: requireOption(options, 'hostname'),
    emails,
    emailDomains,
    name: options.name ?? options.hostname[0],
    sessionDuration: options.session ?? DEFAULT_SESSION_DURATION,
  };
  const output = await runWithClient(options, (client) => configureAccess(client, settings));
  return output.result?.blocked?.length ? { ok: false, ...output } : output;
}

async function runPagesDomain(options) {
  const settings = {
    accountId: accountIdOf(options),
    project: requireOption(options, 'project'),
    domains: requireOption(options, 'domain'),
  };
  return runWithClient(options, (client) => addPagesDomains(client, settings));
}

async function runDns(options) {
  const hostnames = requireOption(options, 'hostname');
  if (hostnames.length > 1) throw new UsageError('dns takes one --hostname per call');
  const settings = {
    hostname: hostnames[0],
    target: requireOption(options, 'target'),
    zone: options.zone ?? null,
    proxied: parseBoolean(options.proxied, 'proxied', true),
    external: Boolean(options.external),
  };
  const output = await runWithClient(options, (client) => configureDns(client, settings));
  return output.result?.mode === 'external' ? { ...output, mode: 'instructions' } : output;
}

async function runVerify(options) {
  const urls = requireOption(options, 'url');
  const results = [];
  for (const url of urls) results.push(await verifyUrl(url, { expectAccess: Boolean(options['expect-access']) }));
  return { ok: results.every((result) => result.ok), results };
}

const SUBCOMMANDS = {
  detect: async (options) => detectProject(resolve(options.cwd ?? '.')),
  scaffold: runScaffold,
  auth: runAuth,
  access: runAccess,
  'pages-domain': runPagesDomain,
  dns: runDns,
  verify: runVerify,
};

async function main() {
  const { subcommand, options } = parseArgs(process.argv.slice(2));
  const handler = SUBCOMMANDS[subcommand];
  if (!handler) throw new UsageError(subcommand ? `unknown subcommand: ${subcommand}` : 'missing subcommand');
  const output = await handler(options);
  print(output);
  return output.ok === false ? EXIT_FAILURE : EXIT_OK;
}

main()
  .then((code) => {
    process.exitCode = code;
  })
  .catch((error) => {
    if (error instanceof UsageError) {
      process.stderr.write(`${error.message}\n${USAGE}\n`);
      process.exitCode = EXIT_USAGE;
      return;
    }
    process.stderr.write(`${error.message}\n`);
    process.exitCode = EXIT_FAILURE;
  });
